fn observe(r:u64,m:usize,zeta:u64,k:u64,b:u64)->Observation{let mut z=1;let mut f=[0;3];for _ in 0..m{let s=pow((k+r-mul(b,z,r))%r,(r-1)/2,r);f[0]=(f[0]+s)%r;f[1]=(f[1]+mul(z,s,r))%r;f[2]=(f[2]+mul(pow(z,r-2,r),s,r))%r;z=mul(z,zeta,r)}Observation{b,f}}
fn caps()->Caps{Caps{terms:128,stored:500000,pairs:2000000,output:64}}
fn root_polynomial(r:u64,roots:&[u64])->Vec<u64>{let mut p=polynomial::Poly::new(r).unwrap();let mut q=vec![1];for &y in roots{q=p.mul(&q,&[(r-y)%r,1]);}q}
fn sparse_eval(f:&Sparse,y:u64,r:u64)->u64{f.iter().fold(0,|s,(&e,&c)|(s+mul(c,pow(y,e as u64,r),r))%r)}
fn selected_public_checks(){let(mut baseline_calls,mut baseline_pairs)=(0,0);let(mut cases,mut extracted,mut endpoints,mut unresolved,mut limited,mut calls,mut pairs,mut guards)=(0,0,0,0,0,0,0,0);
 for(p,a,b,r,base,m)in[(17u64,2u64,2u64,19u64,[5u64,1u64],3usize),(257,1,7,281,[1,3],5)]{let curve=group::Curve::new(p,a,b);let bp=group::Point{x:base[0],y:base[1]};assert_eq!(multiple(curve,bp,r),None);let source=source::Source::new(p,a,b,r,base,64).unwrap();let zeta=(2..r).find(|&z|pow(z,m as u64,r)==1&&(1..m).all(|j|pow(z,j as u64,r)!=1)).unwrap();let ks:Vec<_>=if r==19{(0..r).collect()}else{vec![0,1,2,3,7,17,31,63,127,280]};
  for k in ks{let target=multiple(curve,bp,k);let got=recover_selected(&source,curve,bp,target,r,m,zeta,&[2,1,3,2],1+4*m,100000,caps(),256).unwrap();let old=recover_projector(&source,curve,bp,target,r,m,zeta,&[2,1,3,2],1+4*m,100000,caps()).unwrap();baseline_calls+=old.calls;baseline_pairs+=old.stats.pairs;assert_eq!(got.scalar,old.scalar);assert_eq!(got.calls,old.calls);assert_eq!(got.degree,old.degree);if let Some(j)=got.scalar{assert_eq!(j,k);}match got.route{"selected-singleton"=>{assert_eq!(got.degree,Some(1));extracted+=1},"endpoint"=>endpoints+=1,"image-unresolved"=>unresolved+=1,"projector-cap"=>limited+=1,_=>panic!("unexpected route")};cases+=1;calls+=got.calls;pairs+=got.stats.pairs;
   if k!=0{let guard=recover_selected(&source,curve,bp,target,r,m,zeta,&[2],1,100000,caps(),256).unwrap();assert_eq!(guard.route,"call-cap");assert_eq!(guard.calls,1);guards+=1;}
  }
 }
 println!("public_baseline_calls={baseline_calls} public_baseline_pairs={baseline_pairs}");assert!(extracted>0);println!("public_cases={cases} extracted_and_verified={extracted} identity_endpoints={endpoints} unresolved={unresolved} capped={limited} source_calls={calls} selected_pairs={pairs} call_guards={guards}");
}
fn matrix_rank(mut a:Vec<Vec<u64>>,r:u64)->usize{let n=a.len();let mut rank=0;for j in 0..n{if let Some(i)=(rank..n).find(|&i|a[i][j]!=0){a.swap(rank,i);let inv=pow(a[rank][j],r-2,r);for x in &mut a[rank]{*x=mul(*x,inv,r)}for i in 0..n{if i==rank{continue}let c=a[i][j];for k in j..n{a[i][k]=(a[i][k]+r-mul(c,a[rank][k],r))%r;}}rank+=1;}}rank}
fn selected_checks(){let(mut pairs,mut ranks,mut max_probes)=(0,0,0);
 for(r,l)in[(17u64,1usize),(17,2),(17,4),(17,8),(19,1),(19,3),(19,9),(97,1),(97,3),(97,8),(97,16)]{for epsilon in [1,r-1]{
  let sample=|kind|->Sparse{(0..l).filter_map(|i|{let c=match kind{0=>0,1=>u64::from(i==0),2=>u64::from(i+1==l),3=>1,4=>(i as u64+1)%r,5=>if i%2==0{2}else{0},6=>if i==0||i+1==l{r-1}else{0},_=>(7*i as u64+3)%r};if c==0{None}else{Some((i,c))}}).collect()};
  for ka in 0..8{for kb in 0..8{let a=sample(ka);let b=sample(kb);let mut ring=PhaseAlgebra::new(r,l,epsilon,caps()).unwrap();let mut stats=PairingStats::default();let got=ring.selected_product(&a,&b,2*a.len().min(b.len()),&mut stats).unwrap();let product=ring.product(&a,&b).unwrap();let c0=product.get(&0).copied().unwrap_or(0);let c1=product.get(&(l-1)).copied().unwrap_or(0);assert_eq!(got,[mul(l as u64,c0,r),mul(mul(l as u64,epsilon,r),c1,r)]);assert!(stats.probes<=2*a.len().min(b.len()));max_probes=max_probes.max(stats.probes);pairs+=1;}}
  let mut matrix=vec![vec![0;l];l];for i in 0..l{for j in 0..l{let mut ring=PhaseAlgebra::new(r,l,epsilon,caps()).unwrap();let v=ring.product(&Sparse::from([(i,1)]),&Sparse::from([(j,1)])).unwrap();matrix[i][j]=v.get(&0).copied().unwrap_or(0);}}assert_eq!(matrix_rank(matrix,r),l);ranks+=1;
 }}
 let(mut systems,mut old_pairs,mut new_pairs,mut terminal_probes,mut terminal_products)=(0,0,0,0,0);
 for(r,m)in[(19u64,3usize),(41,5),(97,3),(281,7)]{let zeta=(2..r).find(|&z|pow(z,m as u64,r)==1&&(1..m).all(|j|pow(z,j as u64,r)!=1)).unwrap();let ks:Vec<_>=if r==19{(1..r).collect()}else{vec![1,2,3,7,17,r-1]};let radii=[2,1,3,2];
  for k in ks{for t in [1,4]{for sign in [1,r-1]{let obs:Vec<_>=radii[..t].iter().map(|&b|observe(r,m,zeta,k,b)).collect();let problem=ProjectorProblem::build(r,m,sign,&obs,100000).unwrap();let(q,indicator,prior)=problem.extract(caps()).unwrap();let(got,stats,terminal)=problem.selected(Caps{output:0,..caps()},256).unwrap();let d=q.len()-1;let sum=if d==0{0}else{(r-q[d-1])%r};assert_eq!(got,[d as u64,sum]);if d==1{assert_eq!(problem.sys.phase_at(got[1]).unwrap(),problem.sys.phase_at((r-q[0])%r).unwrap());}old_pairs+=prior.pairs;new_pairs+=stats.pairs;terminal_probes+=terminal.probes;terminal_products+=terminal.products;assert!(indicator.len()<=problem.l);systems+=1;
  }}}
 }
 let mut ring=PhaseAlgebra::new(17,8,1,caps()).unwrap();let a=Sparse::from([(0,1)]);assert!(matches!(ring.selected_product(&a,&a,1,&mut PairingStats::default()),Err(Error::Limit)));assert_eq!(ring.stats.limit,Some("probes"));
 let mut ring=PhaseAlgebra::new(17,8,1,Caps{pairs:0,..caps()}).unwrap();assert!(matches!(ring.selected_product(&a,&a,2,&mut PairingStats::default()),Err(Error::Limit)));assert_eq!(ring.stats.limit,Some("pairs"));
 let mut ring=PhaseAlgebra::new(17,8,1,caps()).unwrap();assert!(matches!(ring.selected_product(&Sparse::from([(8,1)]),&a,2,&mut PairingStats::default()),Err(Error::Domain)));
 let r=998244353;let l=71303168;let mut ring=PhaseAlgebra::new(r,l,1,caps()).unwrap();let mut terminal=PairingStats::default();let got=ring.selected_product(&Sparse::from([(l-1,2)]),&Sparse::from([(1,3)]),2,&mut terminal).unwrap();assert_eq!(got,[mul(l as u64,6,r),0]);assert_eq!(terminal.probes,2);assert_eq!(terminal.products,1);
 let zeta=pow(3,(r-1)/7,r);let obs:Vec<_>=[2,1,3,2].iter().map(|&b|observe(r,7,zeta,17,b)).collect();let problem=ProjectorProblem::build(r,7,pow(17,(r-1)/2,r),&obs,100000).unwrap();let(e,stats,terminal)=problem.selected(Caps{terms:64,stored:100000,pairs:2000000,output:8},128).err().unwrap();assert_eq!(e,Error::Limit);assert_eq!(stats.limit,Some("terms"));assert_eq!(terminal.probes,0);assert_eq!(stats.pairs,14621);
 println!("pairing_equalities={pairs} full_rank_controls={ranks} max_kernel_probes={max_probes} transcript_moment_equalities={systems} predecessor_pairs={old_pairs} selected_pairs={new_pairs} terminal_probes={terminal_probes} terminal_products={terminal_products}");
 println!("large_L={l} supplied_sparse_operand_probes=2 supplied_sparse_operand_products=1 transcript_refusal={:?} pairs_before_refusal={} terminal_probes_before_refusal={} new_cap_controls=2",stats.limit,stats.pairs,terminal.probes);
}
